import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.a5no_H3L.js";const o=JSON.parse('{"title":"镜像队列","description":"⚠️ 镜像队列（Mirrored Queue）自 RabbitMQ 3.9 弃用、4.0 移除，被 Quorum Queue 取代。本章仅作历史参考。","frontmatter":{},"headers":[],"relativePath":"rabbitmq/07-clustering/chapter-02-mirrored-queue.md","filePath":"rabbitmq/07-clustering/chapter-02-mirrored-queue.md"}'),s={name:"rabbitmq/07-clustering/chapter-02-mirrored-queue.md"};function l(d,e,n,u,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="镜像队列" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">镜像队列 <a class="header-anchor" href="#镜像队列" aria-label="Permalink to &quot;镜像队列&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><p data-src-line="3" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">⚠️ 镜像队列（Mirrored Queue）自 RabbitMQ 3.9 弃用、4.0 移除，被 Quorum Queue 取代。本章仅作历史参考。</p></blockquote><h2 id="_1-镜像队列的原理" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">1. 镜像队列的原理 <a class="header-anchor" href="#_1-镜像队列的原理" aria-label="Permalink to &quot;1. 镜像队列的原理&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Queue: order.queue</span></span>
<span class="line"><span>  Master (Node 1) ← 所有读写</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─ Mirror (Node 2) ← 异步复制</span></span>
<span class="line"><span>    └─ Mirror (Node 3) ← 异步复制</span></span></code></pre></div><ul data-src-line="15" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><li data-src-line="15" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">所有读写都走 Master</li><li data-src-line="16" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">Master 将消息异步复制到 Mirror</li><li data-src-line="17" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">Master 故障后，最老的 Mirror 默认提升为新 Master，可能因未同步而丢失消息</li></ul><h2 id="_2-镜像队列的问题" tabindex="-1" data-src-line="19" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">2. 镜像队列的问题 <a class="header-anchor" href="#_2-镜像队列的问题" aria-label="Permalink to &quot;2. 镜像队列的问题&quot;">​</a></h2><table tabindex="0"><thead data-src-line="21" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><tr data-src-line="21" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="23" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><tr data-src-line="23" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><td style="text-align:left;">异步复制</td><td style="text-align:left;">Master 故障时，尚未同步到被提升 Mirror 的消息可能丢失</td></tr><tr data-src-line="24" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><td style="text-align:left;">故障转移</td><td style="text-align:left;">默认提升最老的 Mirror，受 ha-promote-on-failure 策略影响</td></tr><tr data-src-line="25" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><td style="text-align:left;">性能开销</td><td style="text-align:left;">所有队列操作由 Master 处理，复制还增加网络与节点开销</td></tr><tr data-src-line="26" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><td style="text-align:left;">网络分区</td><td style="text-align:left;">是否脑裂取决于分区处理策略，不必然出现多个 Master</td></tr></tbody></table><h2 id="_3-为什么迁移到-quorum-queue" tabindex="-1" data-src-line="28" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">3. 为什么迁移到 Quorum Queue <a class="header-anchor" href="#_3-为什么迁移到-quorum-queue" aria-label="Permalink to &quot;3. 为什么迁移到 Quorum Queue&quot;">​</a></h2><table tabindex="0"><thead data-src-line="30" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><tr data-src-line="30" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><th style="text-align:left;">维度</th><th style="text-align:left;">镜像队列</th><th style="text-align:left;">Quorum Queue</th></tr></thead><tbody data-src-line="32" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><tr data-src-line="32" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><td style="text-align:left;">复制机制</td><td style="text-align:left;">主副本向镜像副本异步复制</td><td style="text-align:left;">基于 Raft 的多数派提交</td></tr><tr data-src-line="33" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><td style="text-align:left;">消息安全</td><td style="text-align:left;">故障时可能丢失尚未同步到被提升副本的消息</td><td style="text-align:left;">已确认消息受多数派提交机制保护</td></tr><tr data-src-line="34" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><td style="text-align:left;">故障转移</td><td style="text-align:left;">默认提升最老的 Mirror，结果受同步状态影响</td><td style="text-align:left;">通过 Raft 选举新 Leader，遵循日志安全规则</td></tr><tr data-src-line="35" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><td style="text-align:left;">设计侧重点</td><td style="text-align:left;">以镜像复制换取高可用</td><td style="text-align:left;">侧重数据安全与一致性</td></tr></tbody></table><p data-src-line="37" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md"><strong>结论</strong>：镜像队列已在 4.0 移除，新项目需要复制队列时优先使用 <a href="./../03-queue/chapter-03-quorum-queue.html">Quorum Queue</a>。复制与故障转移机制见 <a href="./chapter-03-quorum-raft.html">Quorum 与 Raft</a>。</p><h2 id="_4-迁移步骤" tabindex="-1" data-src-line="39" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">4. 迁移步骤 <a class="header-anchor" href="#_4-迁移步骤" aria-label="Permalink to &quot;4. 迁移步骤&quot;">​</a></h2><p data-src-line="41" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">队列类型不能通过修改属性原地转换，需要另建 Quorum Queue 承接流量后再切换。生产者面向 Exchange 发布，切换时改的是路由目标（Exchange 绑定或 routing key），消费者也要转向新队列。下面是停机窗口下的简化流程，完整方案见 <a href="./../03-queue/chapter-03-quorum-queue.html">Quorum Queue 的迁移章节</a>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 创建 Quorum Queue，配置 Exchange 绑定</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 停止生产者，确认旧 Queue 不再接收新消息</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 排空旧 Queue，处理未确认消息</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. 调整绑定，让路由指向新 Queue（解除旧 Queue 绑定或改 routing key）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. 把消费者切换到新 Queue，恢复生产并验证</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 6. 确认业务正常后，删除旧 Queue 和镜像策略</span></span></code></pre></div><p data-src-line="52" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">以上流程省略了消息搬运、重复投递处理和回滚步骤，生产迁移前需按停机窗口与消息量选择具体方案。</p><p data-src-line="54" data-src-file="rabbitmq/07-clustering/chapter-02-mirrored-queue.md">清理策略前先查看实际生效的策略名称，不要假设都叫 ha-all；同一策略可能匹配多个队列，确认不再被其他队列需要后再清理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list_policies</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # / 是默认虚拟主机，按实际环境替换</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rabbitmqctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear_policy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-policy</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # my-policy 替换为实际策略名</span></span></code></pre></div>`,16)])])}const m=t(s,[["render",l]]);export{o as __pageData,m as default};
